 17	    public Main() {
 18	        mainPanel = new JPanel();
 19	        mazeLabels = new MazeLabel[20][25];
 20	        startBtn = new JButton("深度优先算法开始");
 21	        primStart = new JButton("随机Prim算法开始");
 22	        refresh = new JButton("刷新");
 23	        findWayBtn = new JButton("寻找一条路");
 24	        initFrame();
 25	        initPanel();
 26	        initTable();
 27	        initComp();
 28	        setVisible(true);
 29	    }
