 31	    private void initFrame() {
 32	        setSize(900, 622);
 33	        setLocationRelativeTo(null);
 34	        setTitle("Maze");
 35	        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
 36	        setResizable(false);
 37	    }
 38	
 39	    private void initPanel() {
 40	        mainPanel.setLayout(null);
 41	        setContentPane(mainPanel);
 42	    }
 43	
 44	    private void initTable() {
 45	        for(int i = 0; i < 20; i ++) {
 46	            for(int j = 0; j < 25; j ++) {
 47	                mazeLabels[i][j] = new MazeLabel();
 48	                mazeLabels[i][j].setBounds(150 + j * 30, i * 30, 30, 30);
 49	                mazeLabels[i][j].row = i;
 50	                mazeLabels[i][j].col = j;
 51	                mainPanel.add(mazeLabels[i][j]);
 52	            }
 53	        }
 54	    }
 55	
 56	    private void initComp(){
 57	        startBtn.setBounds(12, 20, 135, 40);
 58	        startBtn.addActionListener(e -> MazeTools.generateNewMaze());
 59	        mainPanel.add(startBtn);
 60	
 61	        primStart.setBounds(12, 80, 135, 40);
 62	        primStart.addActionListener(e -> PrimGenerate.primGenerate());
 63	        mainPanel.add(primStart);
 64	
 65	        findWayBtn.setBounds(12, 140, 135, 40);
 66	        findWayBtn.addActionListener(e -> GetWay.getWay());
 67	        mainPanel.add(findWayBtn);
 68	
 69	        refresh.setBounds(12, 200, 135, 40);
 70	        refresh.addActionListener(e -> {
 71	            for(int i = 0; i < 20; i ++) {
 72	                for(int j = 0; j < 25; j ++) {
 73	                    mazeLabels[i][j].repaint();
 74	                }
 75	            }
 76	        });
 77	        mainPanel.add(refresh);
 78	
 79	        introductionStr = new String("<html><body><center>深度优先算法<br>又称为递归回溯算法<br>生成的迷宫主路较为明显<br>难度较小<br><br>随机Prim算法<br>生成的迷宫岔路较多<br>难度较大</center></html></body>");
 80	        introduction = new JLabel(introductionStr);
