237	class MazeTools{
238	    private static int row;
239	    private static int col;
240	    private static int top;
241	    private static Random random;
242	
243	    public static void generateNewMaze(){
244	        for(int i = 0; i < 20; i ++) {
245	            for(int j = 0; j < 25; j ++) {
246	                Main.mazeLabels[i][j].initAll();
247	            }
248	        }
249	        top = 0;
250	        row = 0;
251	        col = 0;
252	        random = new Random();
253	        ArrayList<MazeLabel> stack = new ArrayList<>();
254	        stack.add(Main.mazeLabels[0][0]);
255	        while(top >= 0) {
256	            int[] tried = {-1, -1, -1, -1};
257	            int triedNumber = 0;
258	            boolean moved = false;
259	            MazeLabel curLabel = stack.get(top);
260	            row = curLabel.row;
261	            col = curLabel.col;
262	            curLabel.setAlready();
263	            while(triedNumber < 4) {
264	                int direction = random.nextInt(4);
265	                if(tried[direction] == direction) {
266	                    continue;
267	                }
268	                tried[direction] = direction;
269	                switch(direction) {
270	                    case 0:
271	                        if(row >= 1 && !Main.mazeLabels[row - 1][col].getAlready()) {
272	                            curLabel.setUpAlready();
273	                            Main.mazeLabels[row - 1][col].setDownAlready();
274	                            stack.add(Main.mazeLabels[row - 1][col]);
275	                            top ++;
276	                            moved = true;
277	                        }
278	                        break;
279	                    case 1:
280	                        if(row <= 18 && !Main.mazeLabels[row + 1][col].getAlready()) {
281	                            curLabel.setDownAlready();
282	                            Main.mazeLabels[row + 1][col].setUpAlready();
283	                            stack.add(Main.mazeLabels[row + 1][col]);
284	                            top ++;
285	                            moved = true;
286	                        }
287	                        break;
288	                    case 2:
289	                        if(col >= 1 && !Main.mazeLabels[row][col - 1].getAlready()) {
290	                            curLabel.setLeftAlready();
291	                            Main.mazeLabels[row][col - 1].setRightAlready();
292	                            stack.add(Main.mazeLabels[row][col - 1]);
293	                            top ++;
294	                            moved = true;
295	                        }
296	                        break;
297	                    case 3:
298	                        if(col <= 23 && !Main.mazeLabels[row][col + 1].getAlready()) {
299	                            curLabel.setRightAlready();
300	                            Main.mazeLabels[row][col + 1].setLeftAlready();
301	                            stack.add(Main.mazeLabels[row][col + 1]);
302	                            top ++;
303	                            moved = true;
304	                        }
305	                        break;
306	                }
307	                if(moved) {
308	                    break;
309	                }
310	                triedNumber ++;
311	            }
312	            if(!moved) {
313	                stack.remove(top);
314	                top --;
315	            }
316	        }
317	        Main.mazeLabels[19][24].setTarget();
318	        Main.mazeLabels[19][24].repaint();
319	        Main.mazeLabels[0][0].setCurrent();
320	        Main.mazeLabels[0][0].repaint();
321	    }
322	}
