324	class PrimGenerate {
325	    private static int row;
326	    private static int col;
327	    private static Random random;
328	
329	    public static void primGenerate(){
330	        for(int i = 0; i < 20; i ++) {
331	            for(int j = 0; j < 25; j ++) {
332	                Main.mazeLabels[i][j].initAll();
333	            }
334	        }
335	        row = 0;
336	        col = 0;
337	        random = new Random();
338	        ArrayList<String> walls = new ArrayList<>();
339	        Main.mazeLabels[0][0].setAlready();
340	        walls.add("0,0,1,0");
341	        walls.add("0,0,0,1");
342	        while(!walls.isEmpty()) {
343	            int index = random.nextInt(walls.size());
344	            String wall = walls.get(index);
345	            int fromRow = Integer.parseInt(wall.split(",")[0]);
346	            int fromCol = Integer.parseInt(wall.split(",")[1]);
347	            int toRow = Integer.parseInt(wall.split(",")[2]);
348	            int toCol = Integer.parseInt(wall.split(",")[3]);
349	            if(Main.mazeLabels[toRow][toCol].getAlready() ^ Main.mazeLabels[fromRow][fromCol].getAlready()) {
350	                if(toRow < fromRow) {
351	                    Main.mazeLabels[fromRow][fromCol].setUpAlready();
352	                    Main.mazeLabels[toRow][toCol].setDownAlready();
353	                }
354	                if(toRow > fromRow) {
355	                    Main.mazeLabels[fromRow][fromCol].setDownAlready();
356	                    Main.mazeLabels[toRow][toCol].setUpAlready();
357	                }
358	                if(toCol < fromCol) {
359	                    Main.mazeLabels[fromRow][fromCol].setLeftAlready();
360	                    Main.mazeLabels[toRow][toCol].setRightAlready();
361	                }
362	                if(toCol > fromCol) {
363	                    Main.mazeLabels[fromRow][fromCol].setRightAlready();
364	                    Main.mazeLabels[toRow][toCol].setLeftAlready();
365	                }
366	                row = toRow;
367	                col = toCol;
368	                Main.mazeLabels[row][col].setAlready();
369	                if(row >= 1) {
370	                    walls.add(row + "," + col + "," + String.valueOf(row - 1) + "," + col);
371	                }
372	                if(row <= 18) {
373	                    walls.add(row + "," + col + "," + String.valueOf(row + 1) + "," + col);
374	                }
375	                if(col >= 1) {
376	                    walls.add(row + "," + col + "," + row + "," + String.valueOf(col - 1));
377	                }
378	                if(col <= 23) {
379	                    walls.add(row + "," + col + "," + row + "," + String.valueOf(col + 1));
380	                }
381	            }
382	            else {
383	                walls.remove(index);
384	            }
385	        }
386	        Main.mazeLabels[19][24].setTarget();
387	        Main.mazeLabels[19][24].repaint();
388	        Main.mazeLabels[0][0].setCurrent();
389	        Main.mazeLabels[0][0].repaint();
390	    }
391	}
