420	            for(int i = 0; i < 4; i ++) {
421	                if(i == 0) {
422	                    if(Main.mazeLabels[row][col].isUpAlready() && !visit[row - 1][col]) {
423	                        stack.push(curLabel);
424	                        stack.push(Main.mazeLabels[row - 1][col]);
425	                        visit[row][col] = true;
426	                        visit[row - 1][col] = true;
427	                    }
428	                }
429	                else if(i == 1) {
430	                    if(Main.mazeLabels[row][col].isDownAlready() && !visit[row + 1][col]) {
431	                        stack.push(curLabel);
432	                        stack.push(Main.mazeLabels[row + 1][col]);
433	                        visit[row][col] = true;
434	                        visit[row + 1][col] = true;
435	                    }
436	                }
437	                else if(i == 2) {
438	                    if(Main.mazeLabels[row][col].isLeftAlready() && !visit[row][col - 1]) {
439	                        stack.push(curLabel);
440	                        stack.push(Main.mazeLabels[row][col - 1]);
441	                        visit[row][col] = true;
442	                        visit[row][col - 1] = true;
443	                    }
444	                }
445	                else {
446	                    if(Main.mazeLabels[row][col].isRightAlready() && !visit[row][col + 1]) {
447	                        stack.push(curLabel);
448	                        stack.push(Main.mazeLabels[row][col + 1]);
449	                        visit[row][col] = true;
450	                        visit[row][col + 1] = true;
451	                    }
452	                }
453	            }
454	        }
455	    }
456	
457	    private static void showRes() {
458	        ArrayList<MazeLabel> way = stack.getList();
459	        ArrayList<MazeLabel> deadEnds = new ArrayList<>();
460	        for(int i = 0; i < way.size() - 2; i ++) {
461	            if(way.get(i) == way.get(i + 2)) {
462	                deadEnds.add(way.get(i + 1));
463	            }
464	        }
465	        for(int i = deadEnds.size() - 1; i >= 0; i --) {
466	            int index = way.indexOf(deadEnds.get(i));
467	            way.remove(index + 1);
468	            way.remove(index);
469	        }
470	        for(int i = 0; i < way.size() - 1; i ++) {
471	            MazeLabel curLabel = way.get(i);
472	            MazeLabel nextLabel = way.get(i + 1);
473	            if(nextLabel.row - curLabel.row == 1) {
474	                curLabel.downWay = true;
475	                nextLabel.upWay = true;
476	            }
477	            else if(curLabel.row - nextLabel.row == 1) {
478	                curLabel.upWay = true;
479	                nextLabel.downWay = true;
480	            }
481	            else if(nextLabel.col - curLabel.col == 1) {
482	                curLabel.rightWay = true;
483	                nextLabel.leftWay = true;
484	            }
485	            else if(curLabel.col - nextLabel.col == 1) {
486	                curLabel.leftWay = true;
487	                nextLabel.rightWay = true;
488	            }
489	        }
490	    }
491	}
