import java.util.*;

public class Harness {

    static void initGrid() {
        Main.mazeLabels = new MazeLabel[20][25];
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                MazeLabel l = new MazeLabel();
                l.row = i;
                l.col = j;
                Main.mazeLabels[i][j] = l;
            }
        }
    }

    static String dumpWalls() {
        StringBuilder sb = new StringBuilder();
        int carved = 0, alreadyCount = 0;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                MazeLabel l = Main.mazeLabels[i][j];
                sb.append(l.isUpAlready() ? 'U' : '.');
                sb.append(l.isDownAlready() ? 'D' : '.');
                sb.append(l.isLeftAlready() ? 'L' : '.');
                sb.append(l.isRightAlready() ? 'R' : '.');
                sb.append(l.getAlready() ? '*' : '-');
                sb.append(l.isWin() ? '!' : '_');
                sb.append(' ');
                if (l.isDownAlready()) carved++;
                if (l.isRightAlready()) carved++;
                if (l.getAlready()) alreadyCount++;
            }
            sb.append('\n');
        }
        sb.append("carvedEdges=").append(carved).append(" alreadyCells=").append(alreadyCount).append('\n');
        return sb.toString();
    }

    static String dumpWays() {
        StringBuilder sb = new StringBuilder();
        int marks = 0;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                MazeLabel l = Main.mazeLabels[i][j];
                sb.append(l.upWay ? 'u' : '.');
                sb.append(l.downWay ? 'd' : '.');
                sb.append(l.leftWay ? 'l' : '.');
                sb.append(l.rightWay ? 'r' : '.');
                sb.append(' ');
                if (l.upWay) marks++;
                if (l.downWay) marks++;
                if (l.leftWay) marks++;
                if (l.rightWay) marks++;
            }
            sb.append('\n');
        }
        sb.append("wayMarks=").append(marks).append('\n');
        return sb.toString();
    }

    // Parse a wall file of the "UDLR*_" format produced by dumpWalls and apply it.
    static void applyWalls(String path) throws IOException {
        BufferedReader br = new BufferedReader(new FileReader(path));
        for (int i = 0; i < 20; i++) {
            String line = br.readLine();
            String[] tok = line.trim().split("\\s+");
            for (int j = 0; j < 25; j++) {
                String t = tok[j];
                MazeLabel l = Main.mazeLabels[i][j];
                if (t.charAt(0) == 'U') l.setUpAlready();
                if (t.charAt(1) == 'D') l.setDownAlready();
                if (t.charAt(2) == 'L') l.setLeftAlready();
                if (t.charAt(3) == 'R') l.setRightAlready();
                if (t.charAt(4) == '*') l.setAlready();
            }
        }
        br.close();
    }

    // Structural invariants that must hold for any correct maze, checked without
    // relying on exact random values.
    static String invariants() {
        int sym = 0, asym = 0;
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                MazeLabel l = Main.mazeLabels[i][j];
                if (i < 19) {
                    if (l.isDownAlready() == Main.mazeLabels[i + 1][j].isUpAlready()) sym++; else asym++;
                }
                if (j < 24) {
                    if (l.isRightAlready() == Main.mazeLabels[i][j + 1].isLeftAlready()) sym++; else asym++;
                }
                if (i == 0 && l.isUpAlready()) asym++;
                if (i == 19 && l.isDownAlready()) asym++;
                if (j == 0 && l.isLeftAlready()) asym++;
                if (j == 24 && l.isRightAlready()) asym++;
            }
        }
        // connectivity from (0,0) via carved passages
        boolean[][] seen = new boolean[20][25];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{0, 0});
        seen[0][0] = true;
        int reached = 1;
        while (!q.isEmpty()) {
            int[] c = q.poll();
            int r = c[0], k = c[1];
            MazeLabel l = Main.mazeLabels[r][k];
            if (l.isUpAlready() && r > 0 && !seen[r - 1][k]) { seen[r - 1][k] = true; reached++; q.add(new int[]{r - 1, k}); }
            if (l.isDownAlready() && r < 19 && !seen[r + 1][k]) { seen[r + 1][k] = true; reached++; q.add(new int[]{r + 1, k}); }
            if (l.isLeftAlready() && k > 0 && !seen[r][k - 1]) { seen[r][k - 1] = true; reached++; q.add(new int[]{r, k - 1}); }
            if (l.isRightAlready() && k < 24 && !seen[r][k + 1]) { seen[r][k + 1] = true; reached++; q.add(new int[]{r, k + 1}); }
        }
        return "wallSymmetryOK=" + sym + " wallSymmetryBAD=" + asym + " reachableFrom00=" + reached + "\n";
    }

    public static void main(String[] args) throws Exception {
        String mode = args[0];
        PrintStream out = new PrintStream(new FileOutputStream(args[1]), true, "UTF-8");
        initGrid();
        if (mode.equals("dfs")) {
            MazeTools.generateNewMaze();
            out.print(dumpWalls());
            out.print(invariants());
            GetWay.getWay();
            out.print(dumpWays());
        } else if (mode.equals("prim")) {
            PrimGenerate.primGenerate();
            out.print(dumpWalls());
            out.print(invariants());
            GetWay.getWay();
            out.print(dumpWays());
        } else if (mode.equals("solve")) {
            applyWalls(args[2]);
            out.print(dumpWalls());
            GetWay.getWay();
            out.print(dumpWays());
        } else if (mode.equals("stack")) {
            // direct exercise of the Stack class
            Stack s = new Stack();
            out.println("empty=" + s.isEmpty());
            for (int i = 0; i < 6; i++) s.push(Main.mazeLabels[i][i]);
            out.println("top=" + s.getTop().row + "," + s.getTop().col);
            out.println("size=" + s.getList().size());
            while (!s.isEmpty()) {
                MazeLabel l = s.pop();
                out.println("pop=" + l.row + "," + l.col);
            }
            out.println("empty=" + s.isEmpty());
            // MazeLabel state toggles
            MazeLabel l = Main.mazeLabels[3][4];
            out.println("win0=" + l.isWin());
            l.setTarget();
            out.println("win1=" + l.isWin());
            l.setCurrent();
            out.println("win2=" + l.isWin());
            l.disableCurrent();
            out.println("win3=" + l.isWin());
            l.setCurrent();
            l.initAll();
            out.println("win4=" + l.isWin() + " up=" + l.isUpAlready() + " already=" + l.getAlready()
                    + " ways=" + l.upWay + l.downWay + l.leftWay + l.rightWay);
        }
        out.close();
    }
}

import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.*;
import java.security.MessageDigest;
import javax.imageio.ImageIO;

public class GuiDriver {

    static JButton findBtn(Container c, String text) {
        for (Component comp : c.getComponents()) {
            if (comp instanceof JButton && text.equals(((JButton) comp).getText())) return (JButton) comp;
            if (comp instanceof Container) {
                JButton b = findBtn((Container) comp, text);
                if (b != null) return b;
            }
        }
        return null;
    }

    static String render(JFrame f, String pngPath) throws Exception {
        final BufferedImage img = new BufferedImage(f.getWidth(), f.getHeight(), BufferedImage.TYPE_INT_RGB);
        SwingUtilities.invokeAndWait(() -> {
            Graphics2D g = img.createGraphics();
            g.setColor(Color.WHITE);
            g.fillRect(0, 0, img.getWidth(), img.getHeight());
            f.printAll(g);
            g.dispose();
        });
        int[] px = img.getRGB(0, 0, img.getWidth(), img.getHeight(), null, 0, img.getWidth());
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        DataOutputStream dos = new DataOutputStream(bos);
        long nonWhite = 0;
        for (int p : px) { dos.writeInt(p); if ((p & 0xFFFFFF) != 0xFFFFFF) nonWhite++; }
        dos.flush();
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        byte[] h = md.digest(bos.toByteArray());
        StringBuilder sb = new StringBuilder();
        for (byte b : h) sb.append(String.format("%02x", b));
        if (pngPath != null) ImageIO.write(img, "png", new File(pngPath));
        return sb + " nonWhitePx=" + nonWhite + " size=" + img.getWidth() + "x" + img.getHeight();
    }

    // Text description of every label's logical state, independent of pixels.
    static String stateDump() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 20; i++) {
            for (int j = 0; j < 25; j++) {
                MazeLabel l = Main.mazeLabels[i][j];
                sb.append(l.isUpAlready() ? 'U' : '.').append(l.isDownAlready() ? 'D' : '.')
                  .append(l.isLeftAlready() ? 'L' : '.').append(l.isRightAlready() ? 'R' : '.')
                  .append(l.getAlready() ? '*' : '-').append(l.isWin() ? '!' : '_')
                  .append(l.upWay ? 'u' : '.').append(l.downWay ? 'd' : '.')
                  .append(l.leftWay ? 'l' : '.').append(l.rightWay ? 'r' : '.')
                  .append(' ').append(l.getX()).append(':').append(l.getY())
                  .append(':').append(l.getWidth()).append(':').append(l.getHeight())
                  .append(' ');
            }
            sb.append('\n');
        }
        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        String tag = args[0];          // "oracle" or "rebuilt"
        String outFile = args[1];
        PrintStream out = new PrintStream(new FileOutputStream(outFile), true, "UTF-8");

        SwingUtilities.invokeAndWait(() -> new Main());
        JFrame f = (JFrame) Frame.getFrames()[0];

        out.println("title=" + f.getTitle() + " size=" + f.getWidth() + "x" + f.getHeight()
                + " resizable=" + f.isResizable() + " closeOp=" + f.getDefaultCloseOperation()
                + " visible=" + f.isVisible());
        Container cp = f.getContentPane();
        out.println("contentPaneClass=" + cp.getClass().getName() + " layout=" + cp.getLayout()
                + " childCount=" + cp.getComponentCount());
        // enumerate non-MazeLabel children in add order
        for (Component c : cp.getComponents()) {
            if (c instanceof MazeLabel) continue;
            String txt = (c instanceof JButton) ? ((JButton) c).getText()
                       : (c instanceof JLabel) ? ((JLabel) c).getText() : "";
            String extra = (c instanceof JLabel && !(c instanceof JButton))
                       ? (" hAlign=" + ((JLabel) c).getHorizontalAlignment() + " vAlign=" + ((JLabel) c).getVerticalAlignment())
                       : "";
            out.println("child " + c.getClass().getSimpleName() + " [" + txt + "] bounds="
                    + c.getX() + "," + c.getY() + "," + c.getWidth() + "," + c.getHeight() + extra);
        }
        out.println("--- initial grid state ---");
        out.print(stateDump());
        out.println("render.initial=" + render(f, "/tmp/gui_" + tag + "_initial.png"));

        JButton dfs = findBtn(cp, "深度优先算法开始");
        JButton prim = findBtn(cp, "随机Prim算法开始");
        JButton way = findBtn(cp, "寻找一条路");
        JButton refresh = findBtn(cp, "刷新");
        out.println("buttonsFound dfs=" + (dfs != null) + " prim=" + (prim != null)
                + " way=" + (way != null) + " refresh=" + (refresh != null));

        SwingUtilities.invokeAndWait(() -> dfs.doClick());
        out.println("--- after DFS generate ---");
        out.print(stateDump());
        out.println("render.dfs=" + render(f, "/tmp/gui_" + tag + "_dfs.png"));

        SwingUtilities.invokeAndWait(() -> way.doClick());
        out.println("--- after DFS solve ---");
        out.print(stateDump());
        out.println("render.dfsSolved=" + render(f, "/tmp/gui_" + tag + "_dfssolved.png"));

        SwingUtilities.invokeAndWait(() -> prim.doClick());
        out.println("--- after Prim generate ---");
        out.print(stateDump());
        out.println("render.prim=" + render(f, "/tmp/gui_" + tag + "_prim.png"));

        SwingUtilities.invokeAndWait(() -> way.doClick());
        out.println("--- after Prim solve ---");
        out.print(stateDump());
        out.println("render.primSolved=" + render(f, "/tmp/gui_" + tag + "_primsolved.png"));

        SwingUtilities.invokeAndWait(() -> refresh.doClick());
        out.println("--- after refresh ---");
        out.print(stateDump());
        out.println("render.refresh=" + render(f, "/tmp/gui_" + tag + "_refresh.png"));

        out.close();
        System.exit(0);
    }
}

